/// A verb form: which cell of its conjugation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Cell {
    /// The present.
    Present(crate::Mood, crate::Voice, crate::Person, crate::Number),
    /// The present imperative.
    PresentImperative(crate::Voice, crate::ImperativePerson, crate::Number),
    /// The imperfect (indicative only).
    Imperfect(crate::Voice, crate::Person, crate::Number),
    /// The future (no subjunctive or imperative).
    Future(
        crate::FutureMood,
        crate::Voice,
        crate::Person,
        crate::Number,
    ),
    /// The aorist.
    Aorist(crate::Mood, crate::Voice, crate::Person, crate::Number),
    /// The aorist imperative.
    AoristImperative(crate::Voice, crate::ImperativePerson, crate::Number),
    /// The perfect.
    Perfect(crate::Mood, crate::Voice, crate::Person, crate::Number),
    /// The perfect imperative.
    PerfectImperative(crate::Voice, crate::ImperativePerson, crate::Number),
    /// The pluperfect (indicative only).
    Pluperfect(crate::Voice, crate::Person, crate::Number),
    /// The future perfect (no subjunctive or imperative).
    FuturePerfect(
        crate::FutureMood,
        crate::Voice,
        crate::Person,
        crate::Number,
    ),
    /// An infinitive.
    Infinitive(crate::Tense, crate::Voice),
    /// A participle's citation form (masculine nominative singular); decline it with `adjective`.
    Participle(crate::Tense, crate::Voice),
}

impl Cell {
    /// Its place in a paradigm: its group's first cell, then its values
    /// counted in order, the last fastest.
    pub const fn index(self) -> usize {
        match self {
            Cell::Present(mood, voice, person, number) => {
                cell::IND_ACT_1_SG as usize
                    + ((mood as usize * 3 + voice as usize) * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::PresentImperative(voice, imperative_person, number) => {
                cell::PRESENT_IMPERATIVE_ACT_2_SG as usize
                    + (voice as usize * 2 + imperative_person as usize) * 3
                    + number as usize
            }
            Cell::Imperfect(voice, person, number) => {
                cell::IMPERFECT_ACT_1_SG as usize
                    + (voice as usize * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::Future(future_mood, voice, person, number) => {
                cell::FUTURE_IND_ACT_1_SG as usize
                    + ((future_mood as usize * 3 + voice as usize) * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::Aorist(mood, voice, person, number) => {
                cell::AORIST_IND_ACT_1_SG as usize
                    + ((mood as usize * 3 + voice as usize) * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::AoristImperative(voice, imperative_person, number) => {
                cell::AORIST_IMPERATIVE_ACT_2_SG as usize
                    + (voice as usize * 2 + imperative_person as usize) * 3
                    + number as usize
            }
            Cell::Perfect(mood, voice, person, number) => {
                cell::PERFECT_IND_ACT_1_SG as usize
                    + ((mood as usize * 3 + voice as usize) * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::PerfectImperative(voice, imperative_person, number) => {
                cell::PERFECT_IMPERATIVE_ACT_2_SG as usize
                    + (voice as usize * 2 + imperative_person as usize) * 3
                    + number as usize
            }
            Cell::Pluperfect(voice, person, number) => {
                cell::PLUPERFECT_ACT_1_SG as usize
                    + (voice as usize * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::FuturePerfect(future_mood, voice, person, number) => {
                cell::FUTURE_PERFECT_IND_ACT_1_SG as usize
                    + ((future_mood as usize * 3 + voice as usize) * 3 + person as usize) * 3
                    + number as usize
            }
            Cell::Infinitive(tense, voice) => {
                cell::INFINITIVE_PRES_ACT as usize + tense as usize * 3 + voice as usize
            }
            Cell::Participle(tense, voice) => {
                cell::PARTICIPLE_PRES_ACT as usize + tense as usize * 3 + voice as usize
            }
        }
    }
}

/// A verb to inflect: its lemma, and what you know of it. The more you
/// tell, the surer its forms.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Verb<'w> {
    lemma: &'w str,
    given: Vec<(usize, &'w str)>,
    full: bool,
}

impl<'w> Verb<'w> {
    /// The verb `lemma`, as the dictionary writes it.
    #[must_use]
    pub fn new(lemma: &'w str) -> Self {
        Verb {
            lemma,
            given: Vec::new(),
            full: false,
        }
    }

    /// One of its forms you know (a principal part): readings that disagree
    /// with it are dropped.
    #[must_use]
    pub fn given(mut self, cell: impl Into<Cell>, form: &'w str) -> Self {
        self.given.push((cell.into().index(), form));
        self
    }

    /// Its lemma is spelled with every mark the dictionary writes, so
    /// none is hidden (without this, a lemma typed without marks may be
    /// missing some, and its forms are less sure).
    #[must_use]
    pub fn spelled_in_full(mut self) -> Self {
        self.full = true;
        self
    }

    fn known(&self) -> Known<'_> {
        Known {
            forms: &self.given,
            inherent: &[],
            full: self.full,
        }
    }

    /// Its likeliest form in `cell`.
    #[must_use]
    pub fn form(&self, cell: impl Into<Cell>) -> String {
        GRAMMAR.best(self.lemma, cell.into().index(), &self.known())
    }

    /// Every form it may have in `cell`, likeliest first, each with its
    /// probability and why.
    #[must_use]
    pub fn candidates(&self, cell: impl Into<Cell>) -> Vec<Candidate<'static>> {
        GRAMMAR.candidates(self.lemma, cell.into().index(), &self.known())
    }

    /// The conjugations it may follow, likeliest first, each with its probability
    /// and why.
    #[must_use]
    pub fn conjugation(&self) -> Vec<Reading<'static, 'static, Conjugation>> {
        GRAMMAR.readings(self.lemma, &self.known())
    }
}
